customCss:
/* Windows 95: grey bevelled chrome on the Clouds desktop */
:root {
  --w95-raised: inset -1px -1px #0a0a0a, inset 1px 1px #dfdfdf, inset -2px -2px #808080, inset 2px 2px #fff;
  --w95-sunken: inset -1px -1px #fff, inset 1px 1px #808080, inset -2px -2px #dfdfdf, inset 2px 2px #0a0a0a;
  --w95-pressed: inset -1px -1px #fff, inset 1px 1px #0a0a0a, inset -2px -2px #dfdfdf, inset 2px 2px #808080;
  -webkit-font-smoothing: none;
}

/* Square corners everywhere, including Tailwind's rounded-* utilities */
*,
*::before,
*::after {
  border-radius: 0 !important;
}

/* The Clouds wallpaper, drawn in CSS: soft white puffs on a blue sky */
body {
  background:
    radial-gradient(ellipse 16% 7% at 14% 18%, #fff 0, rgba(255, 255, 255, 0.85) 35%, transparent 100%),
    radial-gradient(ellipse 11% 6% at 22% 14%, rgba(255, 255, 255, 0.9) 0, transparent 100%),
    radial-gradient(ellipse 20% 8% at 62% 30%, #fff 0, rgba(255, 255, 255, 0.8) 30%, transparent 100%),
    radial-gradient(ellipse 12% 6% at 71% 25%, rgba(255, 255, 255, 0.9) 0, transparent 100%),
    radial-gradient(ellipse 18% 7% at 30% 58%, #fff 0, rgba(255, 255, 255, 0.8) 30%, transparent 100%),
    radial-gradient(ellipse 10% 5% at 38% 54%, rgba(255, 255, 255, 0.9) 0, transparent 100%),
    radial-gradient(ellipse 22% 8% at 84% 72%, #fff 0, rgba(255, 255, 255, 0.8) 30%, transparent 100%),
    radial-gradient(ellipse 13% 6% at 92% 67%, rgba(255, 255, 255, 0.9) 0, transparent 100%),
    radial-gradient(ellipse 15% 6% at 8% 86%, rgba(255, 255, 255, 0.95) 0, transparent 100%),
    linear-gradient(180deg, #2f62b5 0%, #5a8fd8 55%, #8db6ea 100%);
  background-attachment: fixed;
}

/* Header bar and library sidebar: grey like the taskbar, no glass */
:root .app-header-surface::before,
:root .app-chrome-glass-surface::before {
  background: var(--app-header-bg);
  box-shadow: var(--w95-raised);
}

/* Header tabs (settings, statistics) as buttons, the current one pressed in */
:root .section-nav-item {
  color: #000;
  font-weight: 400;
}

:root .section-nav-item:hover:not(.section-nav-item-active):not(.section-nav-item-disabled) {
  background: #dfdfdf;
  color: #000;
}

:root .section-nav-item-active {
  background: repeating-conic-gradient(#c0c0c0 0 25%, #fff 0 50%) 0 0 / 2px 2px;
  color: #000;
  box-shadow: var(--w95-pressed);
}

/* Sidebar: a sunken search field, list rows selected in navy */
:root .library-sidebar .library-filter-search {
  background: #fff;
  color: #000;
  border: 0;
  box-shadow: var(--w95-sunken);
}

:root .library-sidebar .library-filter-search-input {
  box-shadow: none;
}

:root .library-sidebar .library-filter-row,
:root .library-sidebar .library-filter-section-toggle {
  color: #000;
}

:root .library-sidebar .library-filter-row:hover,
:root .library-sidebar .library-filter-section-toggle:hover {
  background: #dfdfdf;
  color: #000;
}

:root .library-sidebar .library-filter-row-active,
:root .library-sidebar .library-filter-row-active:hover {
  background: #000080;
  color: #fff;
}

:root .library-sidebar .library-filter-row-active .library-filter-count {
  color: #fff;
}

/* Windows: grey face with a raised bevel instead of soft shadows */
:root .app-surface-card,
:root .app-popover-panel,
:root .library-card {
  background: #c0c0c0;
  border: 0;
  box-shadow: var(--w95-raised);
}

:root .app-popover-panel {
  padding: 3px;
}

/* Buttons in the title bar look like the minimise/close buttons */
:root .app-header-pill {
  background: transparent;
  border: 0;
  box-shadow: none;
}

:root .app-header-icon {
  background: #c0c0c0;
  color: #000;
  box-shadow: var(--w95-raised);
}

:root .app-header-icon:hover {
  background: #c0c0c0;
  color: #000;
}

:root .app-header-icon:active,
:root .app-header-icon-active {
  background: repeating-conic-gradient(#c0c0c0 0 25%, #fff 0 50%) 0 0 / 2px 2px;
  color: #000;
  box-shadow: var(--w95-pressed);
}

:root .app-header-icon:focus-visible {
  outline: 1px dotted #000;
  outline-offset: -5px;
}

/* Menu items: navy highlight, white text */
:root .app-popover-item {
  font-weight: 400;
}

:root .app-popover-item:hover,
:root .app-popover-item:focus-visible,
:root .app-popover-item-active {
  background: #000080;
  color: #fff;
}

/* Text fields: white and sunken */
:root :is([type='text'], [type='search'], [type='password'], [type='number'], [type='url'], [type='email'], select, textarea, .reader-panel-input) {
  background-color: #fff;
  color: #000;
  border: 0;
  box-shadow: var(--w95-sunken);
}

/* Reader overlays become dialog windows */
:root .reader-panel {
  border: 0;
  box-shadow: var(--w95-raised);
}

:root .reader-panel-chip {
  background: #c0c0c0;
  color: #000;
  box-shadow: var(--w95-raised);
}

:root .reader-panel-chip:active {
  box-shadow: var(--w95-pressed);
}

/* Notes: a dotted underline as in old help files */
::highlight(ttu-hl-note) {
  text-decoration: underline dotted #000080;
  text-decoration-thickness: 2px;
}

/* Bevelled scrollbars with a dithered track */
@supports selector(::-webkit-scrollbar) {
  * {
    scrollbar-color: auto;
  }

  ::-webkit-scrollbar {
    width: 16px;
    height: 16px;
  }

  ::-webkit-scrollbar-track {
    background: repeating-conic-gradient(#c0c0c0 0 25%, #fff 0 50%) 0 0 / 2px 2px;
  }

  ::-webkit-scrollbar-thumb {
    background: #c0c0c0;
    box-shadow: var(--w95-raised);
  }

  ::-webkit-scrollbar-button:single-button {
    display: block;
    width: 16px;
    height: 16px;
    background: #c0c0c0;
    box-shadow: var(--w95-raised);
  }

  ::-webkit-scrollbar-corner {
    background: #c0c0c0;
  }
}

::selection {
  background: #000080;
  color: #fff;
}
